"""
API 직접 연결 테스트 — 토큰 갱신 없이 현재 브라우저 쿠키 사용
"""
import json, base64, requests
from datetime import date, timedelta

# ── 브라우저에서 복사한 쿠키 원본 그대로 사용 ─────────────────────────────
# (갱신 없이 현재 세션 유효성 확인)
PROJECT_REF = "kiprvkudedkvynhblcqv"
API_BASE    = "https://www.cyclehackers.kr"

# 브라우저에서 가져온 .0 쿠키 값 (base64- 포함 전체)
COOKIE_0 = "base64-"
COOKIE_1 = ""

yesterday = (date.today() - timedelta(days=1)).isoformat()

cookies = {
    f"sb-{PROJECT_REF}-auth-token.0": COOKIE_0,
    f"sb-{PROJECT_REF}-auth-token.1": COOKIE_1,
}

print(f"API 연결 테스트 — 날짜: {yesterday}")

res = requests.get(
    f"{API_BASE}/api/admin/utm-links",
    params={
        "page": 1,
        "limit": 10,
        "metricsStartDate": yesterday,
        "metricsEndDate": yesterday,
        "sortBy": "created_at",
        "sortOrder": "desc",
    },
    cookies=cookies,
    timeout=20,
)

print(f"상태코드: {res.status_code}")
print(f"응답: {res.text[:500]}")
